// Utilidad: deshabilita btn, muestra label de carga, ejecuta fn, restaura
async function withLoading(btn, loadingLabel, fn) {
    if (!btn) return fn();
    const orig = btn.innerHTML;
    const origDisabled = btn.disabled;
    const origColor = btn.style.color;
    btn.disabled = true;
    btn.style.opacity = '0.7';
    // Color propio: el aviso de "guardando" heredaba el de la fila, y la fila de
    // un usuario desactivado va al 50% de opacidad. Entre eso y el 0.7 de aca
    // quedaba practicamente invisible: parecia que el boton se hubiera borrado.
    btn.style.color = 'var(--text-strong)';
    btn.innerHTML = loadingLabel;
    try { return await fn(); }
    finally {
        btn.disabled = origDisabled;
        btn.style.opacity = '';
        btn.style.color = origColor;
        btn.innerHTML = orig;
    }
}

export const showPremiumAlert = (title, message, type = 'error') => {
    return new Promise((resolve) => {
        // Create backdrop container
        const backdrop = document.createElement('div');
        backdrop.style.position = 'fixed';
        backdrop.style.top = '0';
        backdrop.style.left = '0';
        backdrop.style.width = '100vw';
        backdrop.style.height = '100vh';
        backdrop.style.backgroundColor = 'rgba(var(--bg-rgb), 0.75)';
        backdrop.style.backdropFilter = 'blur(12px)';
        backdrop.style.display = 'flex';
        backdrop.style.justifyContent = 'center';
        backdrop.style.alignItems = 'center';
        backdrop.style.zIndex = '999999';
        backdrop.style.opacity = '0';
        backdrop.style.transition = 'opacity 0.25s cubic-bezier(0.4, 0, 0.2, 1)';
        
        // Define colors and icon based on type
        let accentColor = 'var(--danger)'; // Red for error
        let icon = '❌';
        let glowColor = 'rgba(var(--danger-rgb), 0.3)';
        
        if (type === 'success') {
            accentColor = 'var(--success-alt)'; // Green
            icon = '✅';
            glowColor = 'rgba(var(--success-alt-rgb), 0.3)';
        } else if (type === 'warning') {
            accentColor = 'var(--warning)'; // Amber
            icon = '⚠️';
            glowColor = 'rgba(var(--warning-rgb), 0.3)';
        } else if (type === 'info') {
            accentColor = 'var(--blue)'; // Blue
            icon = 'ℹ️';
            glowColor = 'rgba(var(--blue-rgb), 0.3)';
        }

        backdrop.innerHTML = `
            <div class="glass-panel" style="
                width: 90%;
                max-width: 450px;
                padding: 2.5rem 2rem;
                border-radius: 20px;
                background: linear-gradient(135deg, rgba(var(--card-rgb), 0.8) 0%, rgba(var(--bg-rgb), 0.95) 100%);
                border: 1px solid rgba(var(--ink-rgb), 0.08);
                box-shadow: 0 25px 50px -12px rgba(var(--shadow-rgb), 0.5), 0 0 40px ${glowColor};
                display: flex;
                flex-direction: column;
                align-items: center;
                text-align: center;
                transform: scale(0.9);
                transition: transform 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
            ">
                <div style="
                    width: 70px;
                    height: 70px;
                    border-radius: 50%;
                    background: rgba(var(--ink-rgb), 0.03);
                    border: 2px solid ${accentColor};
                    display: flex;
                    justify-content: center;
                    align-items: center;
                    font-size:var(--t-2xl);
                    margin-bottom: 1.5rem;
                    box-shadow: 0 0 20px ${glowColor};
                    animation: pulse-icon 2s infinite;
                ">
                    ${icon}
                </div>
                
                <h3 style="
                    margin: 0 0 0.8rem 0;
                    color: var(--text-strong);
                    font-size:var(--t-xl);
                    font-weight: 800;
                    letter-spacing: 1px;
                    text-transform: uppercase;
                ">
                    ${title}
                </h3>
                
                <p style="
                    margin: 0 0 2rem 0;
                    color: var(--text-muted);
                    font-size:var(--t-md);
                    line-height: 1.6;
                    font-weight: 500;
                ">
                    ${message}
                </p>
                
                <button id="premium-alert-btn" style="
                    width: 100%;
                    padding: 0.8rem;
                    border: none;
                    border-radius: 12px;
                    background: linear-gradient(135deg, ${accentColor} 0%, var(--on-accent) 150%);
                    color: var(--text-strong);
                    font-size:var(--t-md);
                    font-weight: 700;
                    letter-spacing: 1px;
                    cursor: pointer;
                    box-shadow: 0 4px 12px ${glowColor};
                    transition: all 0.2s ease;
                " onmouseover="this.style.transform='translateY(-2px)'; this.style.boxShadow='0 6px 16px ${glowColor}';" 
                  onmouseout="this.style.transform='translateY(0)'; this.style.boxShadow='0 4px 12px ${glowColor}';">
                    ACEPTAR
                </button>
            </div>
            <style>
                @keyframes pulse-icon {
                    0% { transform: scale(1); box-shadow: 0 0 20px ${glowColor}; }
                    50% { transform: scale(1.05); box-shadow: 0 0 30px ${accentColor}; }
                    100% { transform: scale(1); box-shadow: 0 0 20px ${glowColor}; }
                }
            </style>
        `;
        
        document.body.appendChild(backdrop);
        
        setTimeout(() => {
            backdrop.style.opacity = '1';
            backdrop.querySelector('.glass-panel').style.transform = 'scale(1)';
        }, 10);
        
        const closeAlert = () => {
            backdrop.style.opacity = '0';
            backdrop.querySelector('.glass-panel').style.transform = 'scale(0.9)';
            setTimeout(() => {
                backdrop.remove();
                resolve();
            }, 250);
        };
        
        backdrop.querySelector('#premium-alert-btn').onclick = closeAlert;
        backdrop.onclick = (e) => {
            if (e.target === backdrop) closeAlert();
        };
    });
};
window.showPremiumAlert = showPremiumAlert;

